/* Simulated administration. No network integrations or real account changes. */
(()=>{
const protocols=[['zigbee','Zigbee',18,'Mesh network','grid'],['wifi','WiFi',8,'Local network','home'],['mqtt','MQTT',5,'Message broker','plug'],['esphome','ESPHome',3,'Custom controllers','settings'],['ble','Bluetooth (BLE)',2,'Nearby devices','tablet'],['zwave','Z-Wave',1,'Mesh network','grid']];
const partners=[['google','Google Home','google.svg','accent'],['alexa','Amazon Alexa','alexa.png','fan'],['apple','Apple HomeKit','apple.png','climate'],['smartthings','Samsung SmartThings','smartthings.png','energy']];
const sessions=[['pixel',"Jeel’s Pixel",'Android · Administrator','This device','tablet'],['samsung',"Kavya’s Samsung",'Android · Member','Active now','tablet'],['iphone',"John’s iPhone",'iOS · Member','12 min ago','tablet'],['golf','VW Golf GTI','Vehicle · Limited access','38 min ago','home'],['tab','Google Tab','Wall display · Dashboard only','Active now','tablet'],['fridge','Home Fridge','Appliance · Dashboard only','2 hours ago','plug']];
const defaults={enabled:Object.fromEntries([...protocols,...partners].map(p=>[p[0],true])),admin:{approval:true,remote:false,guest:false},timeout:'30',revoked:[]};
let state=structuredClone(defaults);
try{const saved=JSON.parse(localStorage.getItem('fosslink-system-v1'));if(saved)state={...defaults,...saved,enabled:{...defaults.enabled,...saved.enabled},admin:{...defaults.admin,...saved.admin},revoked:Array.isArray(saved.revoked)?saved.revoked:[]}}catch{}
const toggle=(key,on,label,kind='integration')=>`<button class="sys-toggle" role="switch" aria-checked="${on}" aria-label="${esc(label)}" data-sys-${kind}="${key}"><span></span></button>`;
const save=()=>{try{localStorage.setItem('fosslink-system-v1',JSON.stringify(state))}catch{toast('Storage unavailable; changes last for this visit.')}};
systemView=function(){const active=protocols.filter(p=>state.enabled[p[0]]),signed=sessions.filter(s=>!state.revoked.includes(s[0]));return `<div class="system-page">
<header class="sys-heading"><div><span class="sys-kicker">CONTROL CENTRE</span><h1>System</h1><p>Your connections, access and shared devices.</p></div><span class="sys-demo">${icon('info')} Local demo</span></header>
<div class="sys-stats"><article><span>Enabled protocols</span><strong>${active.length}<small> / 6</small></strong></article><article><span>Reachable devices</span><strong>${active.reduce((n,p)=>n+p[2],0)}<small> / 37</small></strong></article><article><span>Signed-in devices</span><strong>${signed.length}<small> sessions</small></strong></article></div>
<section aria-labelledby="protocol-title"><div class="sys-section-title"><div><h2 id="protocol-title">Main integrations</h2><p>Switch a protocol off to pause its demo connection.</p></div><span>37 paired devices</span></div><div class="sys-protocols">${protocols.map(([id,name,count,detail,glyph])=>`<article class="sys-card ${state.enabled[id]?'':'sys-paused'}"><div class="sys-card-top"><span class="sys-icon">${icon(glyph)}</span>${toggle(id,state.enabled[id],name)}</div><h3>${name}</h3><p>${detail}</p><div class="sys-card-bottom"><strong>${count} <span>devices</span></strong><span class="sys-status">${state.enabled[id]?'Connected':'Paused'}</span></div></article>`).join('')}</div></section>
<section aria-labelledby="partners-title"><div class="sys-section-title"><div><h2 id="partners-title">Third-party integrations</h2><p>Manage which ecosystems can access your demo home.</p></div></div><div class="sys-partners">${partners.map(([id,name,mark,color])=>`<article class="sys-partner"><span class="sys-partner-mark" style="--partner:var(--${color})"><img src="assets/brands/${mark}" alt="" width="30" height="30"></span><div><h3>${name}</h3><p>${state.enabled[id]?'Sharing enabled':'Sharing paused'}</p></div>${toggle(id,state.enabled[id],name)}</article>`).join('')}</div></section>
<div class="sys-admin-grid"><section class="sys-panel" aria-labelledby="admin-title"><div class="sys-section-title"><div><h2 id="admin-title">Admin access</h2><p>Permissions for your Fosslink home.</p></div>${icon('settings')}</div>${[['approval','Approve new devices','Require admin approval before a device joins.'],['remote','Remote access','Allow access from outside your home network.'],['guest','Guest control','Let guests operate shared devices.']].map(([id,label,desc])=>`<div class="sys-setting"><div><h3>${label}</h3><p>${desc}</p></div>${toggle(id,state.admin[id],label,'admin')}</div>`).join('')}<label class="sys-setting" for="sys-timeout"><div><h3>Admin session timeout</h3><p>Lock idle administrator sessions.</p></div><select id="sys-timeout">${[['15','15 min'],['30','30 min'],['60','1 hour']].map(([v,l])=>`<option value="${v}" ${state.timeout===v?'selected':''}>${l}</option>`).join('')}</select></label><p class="sys-note">These settings simulate access policies. They do not secure this public demo.</p></section>
<section class="sys-panel" aria-labelledby="sessions-title"><div class="sys-section-title"><div><h2 id="sessions-title">Signed-in devices <span class="sys-count">${signed.length}</span></h2><p>Devices with a Fosslink app session.</p></div></div><div class="sys-sessions">${signed.map(([id,name,role,time,glyph])=>`<article class="sys-session"><span class="sys-session-icon">${icon(glyph)}</span><div><h3>${name}</h3><p>${role}</p><small>${time}</small></div>${id==='pixel'?'<span class="sys-current">Current</span>':`<button class="sys-revoke" data-sys-revoke="${id}" aria-label="Sign out ${esc(name)}">Sign out</button>`}</article>`).join('')}</div>${state.revoked.length?'<button class="sys-restore" data-sys-restore>Restore demo sessions</button>':''}</section></div><p class="sys-note">Sample integration inventory · Counts are independent of Overview’s device cards. Disabling a protocol preserves its paired devices. Settings stay in this browser; connections and sessions are simulated.</p></div>`};
app.addEventListener('click',e=>{const b=e.target.closest('[data-sys-integration],[data-sys-admin],[data-sys-revoke],[data-sys-restore]');if(!b)return;let selector;
if(b.dataset.sysIntegration){const id=b.dataset.sysIntegration;state.enabled[id]=!state.enabled[id];selector=`[data-sys-integration="${id}"]`;toast(`${[...protocols,...partners].find(p=>p[0]===id)[1]} ${state.enabled[id]?'enabled':'paused'} in demo`)}
else if(b.dataset.sysAdmin){const id=b.dataset.sysAdmin;state.admin[id]=!state.admin[id];selector=`[data-sys-admin="${id}"]`;toast('Demo access setting updated')}
else if(b.dataset.sysRevoke){state.revoked.push(b.dataset.sysRevoke);selector='[data-sys-restore]';toast('Demo session signed out')}
else{state.revoked=[];selector='[data-sys-revoke]';toast('Demo sessions restored')}
save();render();app.querySelector(selector)?.focus({preventScroll:true});});
app.addEventListener('change',e=>{if(e.target.id==='sys-timeout'){state.timeout=e.target.value;save();toast('Demo timeout updated')}});
})();
